@r2 syntax.relation marker="to" from=$c1 to=$n3
@n3 syntax.nominal head="Hello"

@c1 syntax.clause form=imperative verb="set" complement=$n1
@n1 syntax.nominal dependent="the" head="text"
@r1 syntax.relation marker="of" from=$n1 to=$n2
@n2 syntax.nominal head="o1"
